package vn.svframe.lively.event;
import vn.svframe.lively.actor.ActorId;import vn.svframe.lively.api.LivelyApi;import vn.svframe.lively.crime.CrimeEngine;import vn.svframe.lively.quest.QuestRuntime;import java.time.*;import java.util.*;public final class LivingWorldDirectorService{private static final ActorId SYSTEM=new ActorId(new UUID(0L,1L),ActorId.Kind.SYSTEM);private long lastPulse;public LivingWorldDirectorService(){installDefaultSeeds();LivelyApi.events().addListener(new WorldEventEngine.Listener(){@Override public void onStarted(WorldEventEngine.WorldEvent e){onEventStarted(e);}});}public void tick(long tick){if(tick-lastPulse<1200L)return;lastPulse=tick;Map<String,Double>s=signals();Set<ActorId>a=LivelyApi.actors().snapshot().actors().keySet();for(WorldEventEngine.EventProposal p:LivelyApi.storySeeds().propose(s,null,a.stream().filter(x->x.kind()==ActorId.Kind.NPC).limit(32).collect(java.util.stream.Collectors.toSet()),2))if(LivelyApi.events().activeEvents().stream().noneMatch(e->e.seed().equals(p.seed())))LivelyApi.events().start(p);emergeAntagonist(s,a);}private void onEventStarted(WorldEventEngine.WorldEvent e){StoryArcEngine.Arc arc=LivelyApi.storyArcs().active().stream().filter(a->a.seed().equals(e.seed())).findFirst().orElseGet(()->LivelyApi.storyArcs().start(e.seed(),title(e),5,Map.of("category",e.category().name())));LivelyApi.storyArcs().attachEvent(arc.id(),e.id(),e.intensity()*.25D);if(e.intensity()>=.42D&&LivelyApi.quests().snapshot().quests().values().stream().noneMatch(q->e.id().toString().equals(q.facts().get("event"))))createQuest(e);}private void createQuest(WorldEventEngine.WorldEvent e){QuestRuntime.ObjectiveType type=switch(e.category()){case CRIME,MYSTERY->QuestRuntime.ObjectiveType.INVESTIGATION;case MIGRATION,DISCOVERY->QuestRuntime.ObjectiveType.EXPLORATION;case FACTION_CONFLICT,FESTIVAL,SOCIAL,POLITICAL->QuestRuntime.ObjectiveType.SOCIAL;case ECONOMIC->QuestRuntime.ObjectiveType.DELIVERY;case DISASTER->QuestRuntime.ObjectiveType.ESCORT;};String target=e.structureId()!=null?e.structureId():e.seed();List<QuestRuntime.Objective>objectives=new ArrayList<>();objectives.add(new QuestRuntime.Objective("main",type,target,1,false,false,Map.of("event",e.id().toString())));if(e.intensity()>.72D)objectives.add(new QuestRuntime.Objective("optional_context",QuestRuntime.ObjectiveType.INVESTIGATION,e.seed(),1,true,true,Map.of("discover","cause")));ActorId issuer=e.participants().stream().filter(a->a.kind()==ActorId.Kind.NPC).findFirst().orElse(SYSTEM);Duration ttl=Duration.between(Instant.now(),e.expiresAt());if(ttl.isNegative()||ttl.isZero())ttl=Duration.ofMinutes(10);long reward=Math.max(100L,Math.min(100000L,Math.round(500D+e.intensity()*4500D)));LivelyApi.quests().create(issuer,null,questTitle(e),objectives,ttl,Map.of("event",e.id().toString(),"seed",e.seed(),"reward_budget",Long.toString(reward),"public","true"));}private void emergeAntagonist(Map<String,Double>s,Set<ActorId>a){if(LivelyApi.events().activeEvents().stream().anyMatch(e->"villain_emergence".equals(e.facts().get("kind"))))return;var c=LivelyApi.storySeeds().antagonistCandidates(LivelyApi.actors(),a.stream().filter(x->x.kind()==ActorId.Kind.NPC).collect(java.util.stream.Collectors.toSet()),s);if(c.isEmpty()||c.get(0).score()<.68D)return;var top=c.get(0);LivelyApi.events().start(new WorldEventEngine.EventProposal(WorldEventEngine.Category.FACTION_CONFLICT,"villain_emergence",null,Set.of(top.actor()),top.score(),Duration.ofHours(6),Map.of("kind","villain_emergence","candidate",top.actor().uuid().toString(),"reason",top.reason())));}private Map<String,Double>signals(){double crime=LivelyApi.crime().snapshot().crimes().values().stream().filter(c->c.status()==CrimeEngine.Status.OPEN||c.status()==CrimeEngine.Status.INVESTIGATING).count();var stocks=LivelyApi.economy().snapshot().stocks().values();double scarcity=stocks.isEmpty()?0D:stocks.stream().mapToDouble(s->Math.max(0D,1D-s.quantity()/(double)Math.max(1L,s.targetQuantity()))).average().orElse(0D);var relations=LivelyApi.factions().snapshot().relations().values();double conflict=relations.isEmpty()?0D:relations.stream().mapToDouble(r->r.hostility()).average().orElse(0D),rumors=Math.min(1D,LivelyApi.social().snapshot().rumors().size()/20D);return Map.of("crime",Math.min(1D,crime/8D),"criminal_underworld",Math.min(1D,crime/10D),"mystery",Math.min(1D,crime/12D+rumors*.25D),"economic_crisis",scarcity,"economic",scarcity,"faction_conflict",conflict,"political_tension",Math.min(1D,conflict*.7D+rumors*.3D));}private void installDefaultSeeds(){if(!LivelyApi.storySeeds().snapshot().isEmpty())return;LivelyApi.storySeeds().register(new StorySeedEngine.Seed("criminal_underworld",WorldEventEngine.Category.CRIME,.65D,true,Map.of()));LivelyApi.storySeeds().register(new StorySeedEngine.Seed("mystery",WorldEventEngine.Category.MYSTERY,.55D,true,Map.of()));LivelyApi.storySeeds().register(new StorySeedEngine.Seed("economic_crisis",WorldEventEngine.Category.ECONOMIC,.50D,true,Map.of()));LivelyApi.storySeeds().register(new StorySeedEngine.Seed("faction_conflict",WorldEventEngine.Category.FACTION_CONFLICT,.60D,true,Map.of()));LivelyApi.storySeeds().register(new StorySeedEngine.Seed("political_tension",WorldEventEngine.Category.POLITICAL,.45D,true,Map.of()));}private static String title(WorldEventEngine.WorldEvent e){return"World arc: "+e.seed();}private static String questTitle(WorldEventEngine.WorldEvent e){return switch(e.category()){case CRIME->"Điều tra: "+e.seed();case MYSTERY->"Làm rõ bí ẩn: "+e.seed();case ECONOMIC->"Nguồn cung bất ổn: "+e.seed();case FACTION_CONFLICT->"Xung đột: "+e.seed();case DISASTER->"Ứng phó: "+e.seed();default->"Tìm hiểu: "+e.seed();};}}
